    // Load data
    val df = spark.read.format("csv").option("header", "true").load("path/to/data.csv")

    // Handle missing data
    val imputer = new Imputer(strategy = "mean").setHandleInvalid("skip")
    val imputedDF = imputer.transform(df)

    // Explore data distribution
