    val pipeline = new Pipeline().setStages(Array(
      new VectorAssembler(inputCols = features._1, outputCol = "features"),
      new LinearRegression(labelCol = "success")
    ))
    val fittedModel = pipeline.fit(imputedDF)
    val predictions = fittedModel.transform(imputedDF).select("success", "predictions")
    val evaluator = new RegressionEvaluator().setLabelCol("success").setPredictionCol("predictions").setMetricName("rmse")
    val rmse = evaluator.evaluate(predictions)

    println(s"RMSE: $rmse")

    // Extract top 5 most important features
    val fedIndices = features._2
    val importantFeatures = imputedDF.columns.filter($(fedIndices)).take(5)

    println(s"Top 5 most important features: $importantFeatures")

