  }

  def diverseFeatureRanking(df: DataFrame): (Array[String], Array[Int]) = {
    // Define function to rank features based on data diversity
    // ...

    // Example using PCA with Mahalanobis distance weighting
    import org.apache.spark.ml.feature.PCA
    import org.apache.spark.ml.linalg.Vectors

    val pca = new PCA(k = 10, maxIter = 100, tol = 1e-6)
    val mahalanobisDF = df.select(imputedDF.columns.map { col =>
      statFunctions(col).astype("double").getAs[org.apache.spark.sql.types.DoubleType](0)
    }: _*)

    val mahalanobisWeighted = mahalanobisDF.rdd.map {
      case (row: Row) =>
        val rowArray = row.toArray
        val covarianceMatrix = row.getAs[Matrix](0)
        val meanVector = row.getAs[Vectors](1)
        val weightedRow = rowArray.map(_ -> mahalanobisWeight(
          Point(rowArray.drop(2).map(_.asInstanceOf[Double])), covarianceMatrix, meanVector))
        new GenericRow(weightedRow)
    }

    val mahalanobisDF2 = mahalanobisWeighted.toDF(imputedDF.columns.tail: _*)

    val mahalanobisModel = pca.fit(mahalanobisDF2)

    val mahalanobisFeatures = mahalanobisModel.featureIndices
    val rankedFeatures = mahalanobisFeatures.map(metric => (imputedDF.columns(metric), metric)).sortBy(_._2)

    (rankedFeatures.map(_._1), rankedFeatures.map(_._2))
  }

  def statFunctions(col: String): Column = {
    col match {
      case "X1" => avg(col).as(col + "_avg")
      case "X2" => stddev(col).as(col + "_stddev")
      // add more functions to calculate relevant statistics
      case _ => col
    }
  }

  def mahalanobisWeight(point: Point, covarianceMatrix: Matrix, meanVector: Vectors): Double = {
    import org.apache.spark.ml.linalg.Vectors

    val diffPoint = point.toArray.map(_ - meanVector.toArray.apply(_))
    val invCovMat = covarianceMatrix.inverse()
    val mahalanobisDistance = Vectors.squaredDistance(diffPoint, invCovMat.multiply(Vectors.dense(diffPoint)))
    math.sqrt(mahalanobisDistance)
  }

}
