// Fonction pour changer l'adresse IP de la caméra
void setIPAddress(std::string ipAddress)
{
    // Initialiser la structure VAPI.result pour récupérer des informations sur les opérations VAPIX
    VAPI.result result;

    // Définir la nouvelle adresse IP pour la caméra
